def downheap(x, i, n):
    if i >= n or 2*i+2 >= n:
        return
    child_min = 2 * i + 1
    if child_min + 1 < n and -x[child_min+1] < -x[child_min]:
        child_min += 1
    if -x[child_min] < -x[i]:
        x[i], x[child_min] = x[child_min], x[i]
        downheap(x, child_min, n)

