        counter = [0] * (max(nums) + 1)
        for num in nums:
            counter[num] += 1
        for i, cnt in enumerate(counter):
            if cnt > 1:
                return i
        return -1

    def bucket_sort():
        n = len(nums) - 1
        bucket = [[] for _ in range(n + 1)]
        for num in nums:
