def find_prime(filename):
    num = 2
    while True:
        is_prime = True
        for line in open(filename):
            for n in map(int, line.split()):
                if num % n == 0 and n != num:
                    is_prime = False
                    break
            if not is_prime:
                break
        if is_prime:
            return num
        num += 1

def main():
    A = find_prime('primes.txt')
    def solve(nums):
        L = len(nums)
        if L < A + 1:
            return []
        for x in range(1, A):
            for p in range(2, L + 1):
                if pow(x, p, L) == 0:
                    return [x]
        ceil = A + 1
        while True:
            is_prime = True
            for x in range(2, ceil + 1):
                if not pow(x, L, ceil + 1) == x:
                    is_prime = False
                    break
            if is_prime:
                return [pow(pow(x, -1, L), -1, L) for x in range(2, ceil + 1)]
            ceil = ceil + L
    return solve

