def powmod_base(r, n, m):
    r %= m
    if n == 0:
        return 1
    x = powmod_base(r, n // 2 % (m - 1), m)
    if n % 2:
        return x * r % m
    return x * x % m

def legendre(a, n):
    cycle = []
    for _ in range(n):
        cycle.append(powmod_base(a, _, n))
        a = (a * a) % n
        if a == 1:
            break
    newcycle = []
    for i in cycle:
        newcycle.append(i % n)
    return tuple(newcycle)

def discriminant(n):
    phi = n - 1
    while (phi % 2) == 0:
        phi //= 2
    factors = []
    for i in range(3, int(phi ** 0.5) + 1, 2):
        if phi % i:
            continue
        factors.append((i, phi // i))
        factors.append((-i, -phi // i))
    factors.append((phi, 1))
    factors.append((-phi, -1))
    for x in range(2, n):
        c = legendre(x, n)
        for factor in factors:
            if c == 1 and factor[1] % 2 == 0:
                other = (x * x + 1) % n
                rem = speed(n, x, other, factor[1] // 2, (n - 1) // 2)
                if rem == 0:
                    return other
    return 0

def speed(n, a1, b1, x, lim):
    if not x and not a1 % n:
        return 0
    for t in range((x // (n - 1) + 1) * (n - 1)):
        a = ((a1 - t * (n - 1)) * b1) % n
        if a < 0:
            a = n + a
        if a > lim:
            return 1
    return 0

