        step_width = 1
        temp_last_step_width = last_step_width
        while temp_last_step_width > 0:
            temp_last_step_width //= 2
            step_width *= 2
        if i ^ n and step_width <= n:
            step_width = (n + 1) // (i + 1)
            last_step_width = step_width
        step_widths.append(step_width)
