def factorial(n):
    """Compute the factorial of a number."""
    m = 1
    v, i = 1, 1
    while i <= n:
        while m > v:
            m //= v
            v *= 2
        while i <= n and m > 1:
            v //= m
            i *= m
        v *= 2
    return i

