    c = [0] * 16
    for i, ai in enumerate(a):
        for j, bi in enumerate(b):
            c[i*4+j] = sum(a2 * b3 for a2, b2 in [(ai >> k & 1, bi >> (3-k) & 1) for k in range(4)])
            c[i*4+j] &= 0xf
    return c

