    a, b = i // 2 * 2, j
    if i < 2 and j < 2:
        fib[i+j] = 1 if i + j == 1 else 0
        return
    multiply(a, b, fib, matrix)
    if i % 2 == 1 and j % 2 == 0:
        fib[i+j] = fib[a] << 1
    elif i % 2 == 0 and j % 2 == 1:
        fib[i+j] = (fib[i] << 1) + fib[a]
    elif i % 2 == 0 and j % 2 == 0:
        fib[i+j] = matrix[multiply_matrix(i, a) + multiply_matrix(j, b) * 16]
    else:
        fib[i+j] = (fib[i] << 1) + ((fib[a] << 1) + fib[b])

