def long_division(dividend, divisor):
    quotient = 0
    remainder = abs(dividend)
    bound = abs(divisor)

    while remainder >= bound:
        temp = 0
        while (bound << temp) <= remainder:
            temp += 1
        remainder -= (1 << (temp - 1)) * bound
        quotient += 1 << (temp - 1)

    if dividend < 0 and quotient % 2 == 0:
        quotient -= 1
    return quotient

