    if n - int(n) >= 0.5:
        return 2 * int((n + 1) / 2)
    else:
        return 2 * int(n / 2)

import math

def solve(n):
    if n <= 1:
        return n
    sqrt_5 = math.sqrt(5)
    phi = (1 + sqrt_5) / 2
    psi = (1 - sqrt_5) / 2
    return int((phi ** n - psi ** n) / sqrt_5)

