def iterative_binomial_coefficient(n, k):
    result = 1
    for i in range(k + 1):
        result = result * (n - i) // i
    return result

def nth_fibo_as_binomial_coefficient(n):
    return iterative_binomial_coefficient(2 * n - 1, n - 1)

def solve_alternative(n):
    assert 0 <= n <= 500
    assert isinstance(n, int)
    return nth_fibo_as_binomial_coefficient(n)

