        visited = [0] * n
        for i in range(n):
            if not dfs(graph, i, visited):
                return False
        return True

    def dfs(graph, node, visited):
        if not visited[node]:
            visited[node] = 1
            for neighbor in graph[node]:
                if visited[neighbor] == 1:
                    return False
                if visited[neighbor] == 0 and not dfs(graph, neighbor, visited):
                    return False
            visited[node] = 2
        return True

    graph = [[] for _ in range(n)]
    for a, b in prerequisites:
        graph[b].append(a)

    if not has_valid_order(graph):
        return []

    order = [0] * n
    visited = [0] * n
    for i in range(n):
        if visited[i] == 0:
            dfs_helper(graph, order, i, visited, 0)

    return order

def dfs_helper(graph, order, node, visited, pos):
    if visited[node] == 1:
        return pos
    visited[node] = 1
    for neighbor in graph[node]:
        pos = dfs_helper(graph, order, neighbor, visited, pos + 1)
    order[pos] = node
    visited[node] = 2
    return pos

