def solve(n, prerequisites):
    timers = [0] * n
    graph = defaultdict(list)
    for _, b in prerequisites:
        graph[b].append(_)

    def dfs(node, visited, path):
        if node in path:
            return False
        if node in visited:
            return True
        visited.add(node)
        path.add(node)
        for neighbor in graph[node]:
            if not dfs(neighbor, visited, path):
                return False
        path.remove(node)
        timers[node] = max(timers[node], max(timers[t] for t in graph[node]))
        return True

    for i in range(n - 1, -1, -1):
        if not dfs(i, set(), set()):
            return []

    return [a for a in range(n) if timers[a] == 0]

