class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, i):
        if self.parent[i] != i:
            self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, a, b):
        pa, pb = self.find(a), self.find(b)
        if pa != pb:
            if self.rank[pa] < self.rank[pb]:
                self.parent[pa] = pb
            elif self.rank[pa] > self.rank[pb]:
                self.parent[pb] = pa
            else:
                self.parent[pb] = pa
                self.rank[pa] += 1

