def solve(nums, k):
    def remove_left_half(arr, target):
        i, n = 0, len(arr)
        while i < n and arr[i] <= target:
            i += 1
        return arr[i:]

    def partial_sort(nums, k):
        if k == 1:
            return min(nums)
        elif k >= len(nums):
            return max(nums)
        else:
            if len(nums) == 1:
                return nums[0]

            half = len(nums) // 2
            left_half = nums[:half]
            right_half = nums[half:]

            pivot = nums[half]

            left_half = remove_left_half(left_half, pivot)
            right_half = remove_left_half(right_half, pivot)

            if k <= len(left_half):
                return partial_sort(left_half, k)
            elif k > len(left_half) + len(right_half):
                return partial_sort(right_half, k - len(left_half) - len(right_half))
            else:
                return pivot

    return partial_sort(sorted(nums), k)

