def solve(nums, k):
    def partition(l, r):
        pivot = random.randint(l, r)
        nums[pivot], nums[r] = nums[r], nums[pivot]
        i = l
        for j in range(l, r):
            if nums[j] < nums[r]:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[r] = nums[r], nums[i]
        return i

    def sort(l, r):
        if l >= r:
            return
        i = partition(l, r)
        if i > k - 1:
            sort(l, i - 1)
        elif i < k - 1:
            sort(i + 1, r)

    n = len(nums)
    for _ in range(n):  # repeated sorting for greater accuracy
        sort(0, n - 1)
    return nums[k - 1]

