    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    heap = Heap()
    for num, freq in count.items():
        if freq >= k:
            return num

        heap.push(-freq)

    while not heap.is_empty():
        freq = -heap.pop()
        if count[nums[len(nums) - freq]] >= k:
            return nums[len(nums) - freq]

    return None

