def solve(nums, k):
    # Insertion sort to maintain a sorted subarray ending at the 'end' index
    def insertion_sort(nums, start, end):
        for i in range(start + 1, end + 1):
            for j in range(i, start, -1):
                if nums[j-1] > nums[j]:
                    nums[j-1], nums[j] = nums[j], nums[j-1]

    # Partial merge sort
    def merge_sort(nums, start, end):
        while start < end:
            mid = (start + end) // 2
            # Sort the two halves independently
            insertion_sort(nums, start, mid)
            insertion_sort(nums, mid + 1, end)
            # Merge the two sorted halves
            i, j, k = start, mid + 1, start
            while i <= mid and j <= end:
                if nums[i] <= nums[j]:
                    nums[k] = nums[i]
                    i += 1
                else:
                    nums[k] = nums[j]
                    j += 1
                k += 1
            # Copy any remaining elements
            while i <= mid:
                nums[k] = nums[i]
                k += 1
                i += 1
            while j <= end:
                nums[k] = nums[j]
                k += 1
                j += 1

    if k <= len(nums) // 2 + 1:
        # We're looking for a small value; sort the first k elements
        insertion_sort(nums, 0, k - 1)
    else:
        # We're looking for a large value; sort the last len(nums) - k + 1 elements
        k = len(nums) - k + 1
        insertion_sort(nums, len(nums) - k + 1, len(nums) - 1)

    # Return the k-th smallest value
    return nums[k - 1]

