def solve(haystack: str, needle: str) -> int:
    """
    Returns the index of the first position at which the string needle occurs as a contiguous substring of the string haystack,
    or -1 if needle is not a substring of haystack.

    Args:
        haystack (str): The string in which to search for the needle.
        needle (str): The string to search for in the haystack.

    Returns:
        int: The index of the first character of the first occurrence of needle in haystack, or -1 if it is not found.
    """

    def KMPSearch(haystack: str, needle: str) -> int:
        le = len(needle)
        lf = len(haystack)

        lps = [0] * le
        j = 0
        i = 1

        while i < le:
            if needle[i] == needle[j]:
                j += 1
                lps[i] = j
                i += 1
            elif j != 0:
                j = lps[j - 1]
            else:
                lps[i] = 0
                i += 1

        i = j = 0

        while i < lf:
            if haystack[i] == needle[j]:
                j += 1
                i += 1

            if j == le:
                return i - j

            elif i < lf and haystack[i] != needle[j]:
                if j != 0:
                    j = lps[j - 1]
                else:
                    i += 1

        return -1

    if len(needle) > len(haystack) or not needle:
        return -1

    return KMPSearch(haystack, needle)

