class DSU:
    def __init__(self, n):
        self.leader = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.leader[x] != x:
            self.leader[x] = self.find(self.leader[x])
        return self.leader[x]

    def union(self, u, v):
        lu, lv = self.find(u), self.find(v)
        if lu == lv: return
        if self.size[lu] < self.size[lv]:
            lu, lv = lv, lu
        self.leader[lv] = lu
        self.size[lu] += self.size[lv]

