class Heap:
    def __init__(self):
        self.values = []

    def insert(self, value):
        self.values.append(value)
        self._bubble_up(len(self.values) - 1)

    def _bubble_up(self, index):
        parent = (index - 1) // 2
        if index <= 0:
            return
        elif self.values[index] < self.values[parent]:
            self.values[index], self.values[parent] = self.values[parent], self.values[index]
            self._bubble_up(parent)

    def delete(self):
        if len(self.values) > 1:
            self.values[0] = self.values[-1]
            del self.values[-1]
            self._min_heapify(0)
            return self.values[0]
        elif len(self.values) == 1:
            value = self.values[0]
            del self.values[0]
            return value
        else:
            return None

    def _min_heapify(self, index):
        left = 2 * index + 1
        right = 2 * index + 2
        smallest = index
        if len(self.values) > left and self.values[left] < self.values[smallest]:
            smallest = left
        if len(self.values) > right and self.values[right] < self.values[smallest]:
            smallest = right
        if smallest != index:
            self.values[index], self.values[smallest] = self.values[smallest], self.values[index]
            self._min_heapify(smallest)

