def minmax_heapify(A, i, n, k):
    left = 2 * i + 1
    right = 2 * i + 2
    smallest = i

    while left < n:
        if k & (1 << (n - 1 - left)) or (A[left] < A[smallest]):
            smallest = left

        if right < n and (k & (1 << (n - 1 - right)) or (A[right] < A[smallest])):
            smallest = right

        i = smallest
        left = 2 * i + 1
        right = 2 * i + 2

