def sort(nums, l, r, k):
    is_sorted = True
    while l < r:
        pivot_index = (l + r) // 2
        if k & (1 << (r - 1 - pivot_index)):
            is_sorted = False
        if nums[pivot_index] < nums[pivot_index - 1] if pivot_index else True:
            nums[pivot_index], nums[r - 1] = nums[r - 1], nums[pivot_index]
            r -= 1
        elif is_sorted:
            l += 1
        else:
            for i in range(l, max(1, l - 2000)):
                if (nums[l - i] < nums[pivot_index] and nums[l - i] > nums[pivot_index - 1]) or nums[l - i] < nums[r - 1 - (l - i)]:
                    break
                if nums[l - i] < nums[pivot_index]:
                    minmax_heapify(nums, l - i, len(nums), k << len(nums))
                    break
                elif nums[l - i] > nums[r - 1 - (l - i)]:
                    minmax_heapify(nums, r - (l - i), len(nums), k << len(nums))
                    break
            for i in range(r, min(r + 2000, len(nums))):
                minmax_heapify(nums, i, len(nums), k << len(nums))
                if i > l and nums[i - 1] > nums[i]:
                    nums[i - 1], nums[i] = nums[i], nums[i - 1]
        if l < r:
            pivot_index = (l + r) // 2
            tmp, nums[pivot_index] = nums[pivot_index], nums[r - 1]
            l = 0
            for i in range(r):
                if k & (1 << (r - 1 - i)):
                    minmax_heapify(nums, i, len(nums), k << len(nums))
                minmax_heapify(nums, r - 1 - i, len(nums), k << len(nums))
                while i and nums[i - 1] > tmp:
                    nums[i], nums[i - 1] = nums[i - 1], nums[i]
                    minmax_heapify(nums, i - 1, len(nums), k << len(nums))
                if nums[i] == tmp:
                    r = i - 1
                    break
            nums[:(r - len(nums))] = sorted(nums[l:r])
            random.shuffle(nums[:(r - len(nums))])
            r = l + len(nums)
            break

    return nums

