    for idx in range(1, len(totals)):
        totals[idx] += totals[idx - 1]
    previous = 0
    sorted_nums = [None] * len(nums)
    kth_MIDDLE_idx = totals[max(int(kth_val - smallest), 0)]
    for v in nums:
        idx = int(v - smallest)
        sorted_nums[totals[idx] - 1] = min(v, sorted_nums[previous - 1] if previous > 0 else None)
        totals[idx] -= 1
        if kth_MIDDLE_idx <= previous:
            return sorted_nums[previous - 1]
        previous = totals[idx]
    return None

import heapq

def solve(nums, k):
    r = range(len(nums))
    return sorted([n for n in nums])[k-1]

def solve_kth_smallest(nums, k):
    return sorted(enumerate(nums), key=lambda x: x[1])[k-1][1]

def solve_heapq(nums, k):
    counter = {}
    for n in nums:
        if n not in counter: counter[n] = 0; heap = []
        counter[n] += 1; heapq.heappush(heap, (n, counter[n]))
    for i in range(k-1):
        h = heapq.heappop(heap)
        counter[h[0]] -= 1
        if counter[h[0]] == 0: del counter[h[0]]
        if heap: heapq.heappush(heap, h)
    return heap[0][0]
